<?php
namespace App\Http\Controllers\Api;use App\Http\Controllers\Controller;use App\Models\SupportTicket;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Str;
class SupportTicketController extends Controller{public function index(Request $r){return SupportTicket::where('user_id',$r->user()->id)->withCount('messages')->latest('last_message_at')->paginate(15);}public function store(Request $r){$data=$r->validate(['subject'=>'required|string|max:200','department'=>'required|in:support,orders,payment,returns','priority'=>'sometimes|in:low,normal,high','order_id'=>'nullable|exists:orders,id','body'=>'required|string|min:5|max:5000']);if(!empty($data['order_id']))abort_unless(DB::table('orders')->where('id',$data['order_id'])->where('user_id',$r->user()->id)->exists(),404);$ticket=DB::transaction(function()use($r,$data){$ticket=SupportTicket::create(['user_id'=>$r->user()->id,'order_id'=>$data['order_id']??null,'number'=>'TKT-'.strtoupper(Str::random(10)),'subject'=>$data['subject'],'department'=>$data['department'],'priority'=>$data['priority']??'normal','last_message_at'=>now()]);$ticket->messages()->create(['user_id'=>$r->user()->id,'body'=>$data['body']]);return $ticket;});return response()->json($ticket,201);}public function show(Request $r,SupportTicket $ticket){$this->own($r,$ticket);$ticket->messages()->where('is_staff',true)->whereNull('read_at')->update(['read_at'=>now()]);return $ticket->load(['messages.user:id,name,avatar','order:id,number']);}public function reply(Request $r,SupportTicket $ticket){$this->own($r,$ticket);abort_if($ticket->status==='closed',422,'این تیکت بسته شده است.');$data=$r->validate(['body'=>'required|string|min:2|max:5000']);$message=$ticket->messages()->create(['user_id'=>$r->user()->id,'body'=>$data['body']]);$ticket->update(['status'=>'customer_reply','last_message_at'=>now()]);return response()->json($message,201);}public function close(Request $r,SupportTicket $ticket){$this->own($r,$ticket);$ticket->update(['status'=>'closed']);return response()->noContent();}private function own(Request $r,SupportTicket $ticket):void{abort_unless($ticket->user_id===$r->user()->id,404);}}
